Method.Source:
/// <summary>
/// DebuC 16.10.23
/// last modified: PaffH 17.03.25
/// </summary>
/// <param name = "inclAlleFirmen">boolean</param>
/// <param name = "_conFirmen">container</param>
/// <returns>container with NDXCompanyBE</returns>
static container uk2con(boolean inclAlleFirmen = false, container _conFirmen = connull())
{
    NDXUmsatzCompanies      nDXUmsatzCompanies;
    container               conUK = connull();
    Query q = new Query();
    QueryBuildDataSource qbds = q.addDataSource(tablenum(NDXUmsatzCompanies));
    qbds.addSortField(fieldnum(NDXUmsatzCompanies, Sorting), SortOrder::Ascending);
    if (!prmisdefault(_conFirmen))
    {
        for (int i=1; i<= conlen(_conFirmen); i++)
        {
            qbds.addRange(fieldnum(NDXUmsatzCompanies, UK)).value(SysQuery::value(conpeek(_conFirmen, i)));
        }
        if (inclAlleFirmen)
        {
            qbds.addRange(fieldnum(NDXUmsatzCompanies, UK)).value(SysQuery::value(NDXCompanyBE::AllCompanies));
        }
    }
    else
    {
        qbds.addRange(fieldnum(NDXUmsatzCompanies, Active)).value(QueryValue(NoYes::Yes));
        if (!inclAlleFirmen)
        {
            qbds.addRange(fieldnum(NDXUmsatzCompanies, UK)).value(SysQuery::valueNot(NDXCompanyBE::AllCompanies));
        }
    }
    QueryRun qr = new QueryRun(q);
    while (qr.next())
    {
        nDXUmsatzCompanies = qr.get(tablenum(NDXUmsatzCompanies));
        //conUK += nDXUmsatzCompanies.UK;
        conUK += NDXHelperCommon::CompanyId2NDXCompany(nDXUmsatzCompanies.CompanyId);
    }
    return conUK;
}

/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "inclAlleFirmen">boolean</param>
/// <param name = "_conFirmen">container</param>
/// <returns>container</returns>
static container CompanyId2con(boolean inclAlleFirmen = false, container _conFirmen = connull())
{
    NDXUmsatzCompanies      nDXUmsatzCompanies;

    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds;
    container               conCompany = connull();
    int                     i;
    ;
    q = new Query();
    qbds = q.addDataSource(tablenum(NDXUmsatzCompanies));
    //--> 1.1: NDX/PAFFH/NDX_TASK1235003759/03.11.2014
    if (!prmisdefault(_conFirmen))
    {
        for (i=1; i<= conlen(_conFirmen); i++)
        {
            qbds.addRange(fieldnum(NDXUmsatzCompanies, UK)).value(SysQuery::value(conpeek(_conFirmen, i)));
        }
        if (inclAlleFirmen)
        {
            qbds.addRange(fieldnum(NDXUmsatzCompanies, UK)).value(SysQuery::value(NDXCompanyBE::AllCompanies));
        }
    }
    else
    {
        //<-- NDX/PAFFH/NDX_TASK1235003759/03.11.2014
        qbds.addRange(fieldnum(NDXUmsatzCompanies, Active)).value(QueryValue(NoYes::Yes));
        if (!inclAlleFirmen)
        {
            qbds.addRange(fieldnum(NDXUmsatzCompanies, UK)).value(SysQuery::valueNot(NDXCompanyBE::AllCompanies));

        }
    }
    qr = new QueryRun(q);
    while (qr.next())
    {
        nDXUmsatzCompanies = qr.get(tablenum(NDXUmsatzCompanies));
        conCompany += nDXUmsatzCompanies.CompanyId;
    }
    return conCompany;
}
